import type { View } from "@effect/ui";
import type { SlackActionPayload } from "../types";
import type * as Slack from "../vocabulary";

export type ButtonStyle = "primary" | "danger";

export interface ButtonOptions<Msg, C extends View.Children<Msg>> {
  /** A stable id for this button. Generated by the host when omitted. */
  readonly actionId?: string;
  readonly style?: ButtonStyle;
  readonly url?: string;
  readonly value?: string;
  readonly disabled?: boolean;
  /** Sends a message when Slack reports a click. */
  readonly onClick?: View.Handler<Msg, SlackActionPayload>;
  readonly children: C;
}

/** A Slack button. Place it in Actions or use it as a Section accessory. */
export const Button = <Msg, C extends View.Children<Msg>>(
  h: Slack.H<Msg>,
  options: ButtonOptions<Msg, C>,
) => {
  const base = h.button
    .attr("actionId", options.actionId)
    .attr("style", options.style)
    .prop("url", options.url)
    .prop("value", options.value)
    .attr("disabled", options.disabled ? "" : undefined);
  const withHandler = options.onClick === undefined ? base : base.on("click", options.onClick);
  return withHandler.children(options.children);
};
